using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The SDK discovers tools by scanning for [McpServerTool] methods
/// in types registered via WithTools<T>().
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // Constructor-injected HttpClient — resolved from DI automatically.
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool("get_weather")]
    [Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.open-meteo.com/v1/forecast" +
                  $"?latitude={latitude}&longitude={longitude}" +
                  $"&current=temperature_2m,wind_speed_10m";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url, cancellationToken)
            ?? throw new InvalidOperationException("Empty response from weather API.");

        var current = response.Current;
        return $"Temperature: {current.Temperature}°C, Wind: {current.WindSpeed} km/h";
    }

    [McpServerTool("get_forecast")]
    [Description("Get a 7-day daily high/low forecast for a location.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.open-meteo.com/v1/forecast" +
                  $"?latitude={latitude}&longitude={longitude}" +
                  $"&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url, cancellationToken)
            ?? throw new InvalidOperationException("Empty response from forecast API.");

        var daily = response.Daily;
        var lines = daily.Time.Select((date, i) =>
            $"{date}: High {daily.Max[i]}°C, Low {daily.Min[i]}°C");

        return string.Join('\n', lines);
    }
}

// ---------- JSON response models ----------

internal sealed class WeatherResponse
{
    [JsonPropertyName("current")]
    public required CurrentWeather Current { get; init; }
}

internal sealed class CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; init; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; init; }
}

internal sealed class ForecastResponse
{
    [JsonPropertyName("daily")]
    public required DailyForecast Daily { get; init; }
}

internal sealed class DailyForecast
{
    [JsonPropertyName("time")]
    public required string[] Time { get; init; }

    [JsonPropertyName("temperature_2m_max")]
    public required double[] Max { get; init; }

    [JsonPropertyName("temperature_2m_min")]
    public required double[] Min { get; init; }
}

